<?php
require_once __DIR__ . '/../config/database.php';
require_once __DIR__ . '/../includes/auth.php';
require_admin();
$pdo = db();
$students = (int)$pdo->query('select count(*) from students')->fetchColumn();
$results = (int)$pdo->query('select count(*) from results')->fetchColumn();
$passed = (int)$pdo->query("select count(*) from results where status = 'PASS'")->fetchColumn();
$failed = (int)$pdo->query("select count(*) from results where status = 'FAIL'")->fetchColumn();
$recent = $pdo->query('select s.roll_number, s.name, r.percentage, r.grade, r.status from results r join students s on s.id = r.student_id order by r.updated_at desc limit 5')->fetchAll();
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>Admin Dashboard</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><div class="admin-layout"><aside class="sidebar"><a class="brand" href="../index.php">Result <span>System</span></a><nav><a class="active" href="dashboard.php">Dashboard</a><a href="students.php">Students</a><a href="results.php">Results</a><a href="logout.php">Logout</a></nav></aside><main class="admin-main"><div class="page-heading"><p class="eyebrow">Administration</p><h1>Dashboard</h1><p class="muted">A quick overview of the result management system.</p></div><div class="stats-grid four"><div class="stat-card"><small>Students</small><strong><?= $students ?></strong></div><div class="stat-card"><small>Results</small><strong><?= $results ?></strong></div><div class="stat-card"><small>Passed</small><strong><?= $passed ?></strong></div><div class="stat-card"><small>Failed</small><strong><?= $failed ?></strong></div></div><section class="panel"><div class="panel-head"><div><h2>Recent Results</h2><p class="muted">Latest published or updated results.</p></div><a class="btn btn-secondary" href="results.php">Manage Results</a></div><div class="table-wrap"><table><thead><tr><th>Roll No</th><th>Name</th><th>Percentage</th><th>Grade</th><th>Status</th></tr></thead><tbody><?php foreach ($recent as $row): ?><tr><td><?= e($row['roll_number']) ?></td><td><?= e($row['name']) ?></td><td><?= e((string)$row['percentage']) ?>%</td><td><?= e($row['grade']) ?></td><td><span class="status-badge <?= $row['status'] === 'PASS' ? 'pass' : 'fail' ?>"><?= e($row['status']) ?></span></td></tr><?php endforeach; ?><?php if (!$recent): ?><tr><td colspan="5" class="empty-cell">No results yet.</td></tr><?php endif; ?></tbody></table></div></section></main></div></body></html>
